function safeURL(raw,base){try{let u=new URL(raw,base);if(u.protocol!=='https:'||!(u.hostname==='columbia.edu'||u.hostname.endsWith('.columbia.edu'))||u.port||u.username||u.password)return null;u.hash='';return u.href}catch{return null}}
