async function draftResponse(request){try{let raw=await request.text();if(raw.length>120000)throw Error('CV is too long.');let b=JSON.parse(raw),url=safeURL(b.url);if(!url)throw Error('Use a Columbia faculty URL.');if(typeof b.cv!=='string'||b.cv.trim().length<80)throw Error('Add CV text before drafting.');let profile=await page(url);let documents=[profile];let researchLinks=[...profile.html.matchAll(/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)].map(m=>({url:safeURL(m[1],profile.url),name:clean(m[2])})).filter(l=>l.url&&l.url!==profile.url&&/research|project|publication|laboratory|lab\b/i.test(l.name)&&!/(pdf|jpg|png)$/i.test(l.url));researchLinks=[...new Map(researchLinks.map(l=>[l.url,l])).values()].slice(0,2);await Promise.all(researchLinks.map(async l=>{try{documents.push(await page(l.url))}catch{}}));let cvTerms=new Set(terms(b.cv+' '+(b.major||'')));let candidates=documents.flatMap(p=>sentences(p.html).map(text=>({text,url:p.url,score:terms(text).filter(t=>cvTerms.has(t)).length+(/research|investigat|develop|focus|project|understand|laboratory|study/i.test(text)?5:0)}))).filter(e=>/research|investigat|develop|focus|project|understand|laboratory|study|model|method/i.test(e.text)).sort((a,b)=>b.score-a.score);if(!candidates.length)throw Error('No clear research description could be extracted. Try the professor’s research or lab page.');let evidence=[...new Map(candidates.map(e=>[e.text,e])).values()].slice(0,2);let allTerms=new Set(evidence.flatMap(e=>terms(e.text)));let cvLines=b.cv.split(/\n|(?<=[.!?])\s+/).map(t=>t.trim()).filter(t=>t.length>25&&t.length<650&&!/@|phone|address|references|https?:/i.test(t));let matched=cvLines.map(text=>({text,score:terms(text).filter(t=>allTerms.has(t)).length})).sort((a,b)=>b.score-a.score)[0];let cvEvidence=matched?.score>0?matched.text:'';let title=clean((profile.html.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i)||[])[1]||(profile.html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)||[])[1]||'');title=title.split(/\|| — | – /)[0].trim();let name=/faculty|research|people|department|laboratory|publications|home/i.test(title)?'[Professor’s name]':title;let shared=[...new Set(terms(evidence[0].text).filter(t=>cvTerms.has(t)))].slice(0,3);let identity=[b.level?b.level.toLowerCase()+' student':'student',b.major?'studying '+b.major:''].filter(Boolean).join(' ');let draft='Subject: Research opportunity inquiry'+(shared.length?' — '+shared.join(', '):'')+'\n\nDear '+name+',\n\nMy name is '+(b.applicant||'[your name]')+', and I am a '+identity+' at [institution]. I was interested in the research described on your Columbia website:\n\n“'+evidence[0].text+'”\n\n'+(cvEvidence?'One relevant part of my background is: '+cvEvidence+'\n\n':'[Add a specific relevant project or skill from your CV.]\n\n')+(shared.length?'The overlap in '+shared.join(', ')+' makes me interested in learning how I could contribute to this work.':'I would like to learn whether my background could be useful to your current work.')+' Are you considering students at my class level for research opportunities? I would appreciate any guidance on prerequisites and the best way to apply.\n\nThank you for your time,\n'+(b.applicant||'[your name]')+'\n\nResearch source: '+evidence[0].url;let connections=[];for(let doc of documents){for(let m of doc.html.matchAll(/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)){let link=safeURL(m[1],doc.url),nm=clean(m[2]),context=clean(doc.html.slice(Math.max(0,m.index-160),m.index+m[0].length+180));if(link&&/^[A-Z][\p{L}.'’-]+(?:\s+[A-Z][\p{L}.'’-]+){1,3}$/u.test(nm)&&/postdoc|graduate student|doctoral|ph\.?d|lab member|research scientist/i.test(context)&&!/University|Columbia|Graduate Student|Research Scientist|Privacy Policy/.test(nm)){connections.push({name:nm,url:link,context,source:doc.url})}}}return Response.json({draft,evidence,cvEvidence,connections:[...new Map(connections.map(c=>[c.url,c])).values()].slice(0,8)})}catch(e){return Response.json({error:e.message},{status:400})}}


